L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "\230\152\142\230\151\165\227\130\168\227\131\158\227\130\146\231\151\133\233\153\162\227\129\171\233\128\163\227\130\140\227\129\166\232\161\140\227\129\143\230\153\130\227\128\129\228\184\128\231\183\146\227\129\171\232\161\140\227\129\141\227\129\159\227\129\132\227\129\163\227\129\166\232\168\128\227\129\163\227\129\166\227\128\130\227\129\157\227\129\134\232\168\128\227\129\136\227\129\176\230\156\128\228\189\142\227\129\167\227\130\130\228\184\128\230\153\169\227\129\175\230\179\138\227\130\129\227\129\166\227\129\143\227\130\140\227\130\139\227\129\168\230\128\157\227\129\134\227\128\130"
