L27_1.m_Talk_VTN = "N\195\179i v\225\187\155i \195\180ng \225\186\165y r\225\186\177ng em mu\225\187\145n gia nh\225\186\173p khi ch\195\186ng ta \196\145\198\176a Emma \196\145\225\186\191n b\225\187\135nh vi\225\187\135n v\195\160o ng\195\160y mai. N\225\186\191u em l\195\160m v\225\186\173y, \195\180ng \225\186\165y s\225\186\189 \196\145\225\187\131 em \225\187\159 l\225\186\161i, \195\173t nh\225\186\165t l\195\160 qua \196\145\195\170m."
L27_1.m_Talk_SCN = "\230\152\142\229\164\169\233\128\129\232\137\190\231\142\155\229\142\187\229\140\187\233\153\162\231\154\132\230\151\182\229\128\153\239\188\140\228\189\160\229\146\140\228\187\150\232\175\180\230\131\179\228\184\128\232\181\183\229\142\187\227\128\130\232\191\153\230\160\183\232\135\179\229\176\145\228\188\154\230\148\182\231\149\153\228\189\160\228\189\143\228\184\128\230\153\154\228\184\138\227\128\130"
L27_1.m_Talk_DEU = "Sag ihm, dass du mitkommen m\195\182chtest, wenn wir Emma morgen ins Krankenhaus bringen. Wenn du das tust, l\195\164sst er dich bleiben, zumindest f\195\188r die Nacht."
